def require(cond, msg):
    if not cond:
        raise RuntimeError("FAIL: " + msg)

def is_sidon(S):
    sums = {}
    for i, a in enumerate(S):
        for b in S[i:]:                      # i <= j, unordered pairs with repetition
            s = a + b
            require(s not in sums, f"non-Sidon: {sums[s]} and {(a,b)} both sum to {s}")
            sums[s] = (a, b)
    return True

def is_maximal(S, N):
    inS = set(S)
    for x in range(1, N + 1):
        if x not in inS and is_sidon(sorted(S + [x])):
            return False                      # extendable => not maximal
    return True

EXPECTED = {1: (1, [1]), 2: (2, [1,2]), 3: (2, [1,3]), 4: (2, [2,3]),
            5: (3, [1,2,4]), 6: (3, [1,2,4]), 7: (3, [1,3,4]), 8: (4, [1,2,4,8])}

for N in range(1, 9):
